      club: { pick: '7, 8 or 9 iron, or PW', note: 'The further the flag and the more green to roll on, the less loft you want.' },
      setup: ['Narrow stance, feet about a fist apart, toes slightly open.', 'Ball off the inside of the right foot so the club meets it on the way down.', '60–70% of your weight on the left foot, and it stays there.', 'Grip down 2–3 cm, hands ahead of the ball, shaft leaning toward the target.', 'Stand closer than usual and let the arms hang, as if putting.'],
