  /* Practice plans: zh = title, blocks = [name, how, caption] in order */
  EN.plans = {
    '15': ['Short Game 15 Minutes', [['Warm-up: 1-metre putts', 'Hit 10 putts through a Gate Drill to find your stroke.', 'Push two tees in in front of the ball as a “gate,” just wider than the putter head. The putter has to pass between them.'], ['Circle Drill', '8 balls 1 metre around the hole; hole them all in a row.', 'With the hole in the middle, push 8 tees in a circle at 1 metre, put a ball by each tee and hole them one by one.'], ['Lag Ladder', 'From 10 / 15 / 20 steps, stop every ball within a metre of the hole.', 'Push in a tee at 10, 15 and 20 steps. Each putt must go further than the last, but not past 20 steps.'], ['Towel landing spot', 'Hit 10 bump and runs and 10 standard chips, landing each on the towel first.', 'Lay a towel one step onto the green. The ball lands on the towel, then rolls to the hole.']]],
    '30': ['Short Game 30 Minutes', [['Warm-up and half swings', 'Stretch, then make 10 half swings from 9 to 3 o’clock with a 56°.', 'Picture standing in the middle of a clock: left arm to 9 on the way back, 3 on the way through, same length both sides.'], ['Short putts: Gate + Circle', '10 putts through the gate, then a 1-metre Circle Drill.', 'Start with a two-tee gate in front of the ball for 10 putts, then circle the hole with 8 tees at 1 metre.'], ['Lag Ladder', 'Two sets of 5 long putts, stopping each within a metre.', 'Push in a tee at 10, 15 and 20 steps. Each putt must go further than the last, but not past 20 steps.'], ['Three-club test', 'Land 7i / 9i / PW on the same spot and note your roll ratios.', 'All three clubs land on the same towel. Watch how far each rolls: PW shortest, 7i longest.'], ['Clock distance chart', 'Hit 5 balls each at 7:30 / 9:00 / 10:30 and note the distances.', 'Stop the left arm at 7:30, 9:00 or 10:30 on the backswing. Bigger swing, longer shot.'], ['Up & Down challenge', 'Pick 3 spots; get down in two (a chip and a putt) from each.', 'Pick a spot in the rough, one on the fringe and one in a bunker. One chip, one putt: in the hole in two to pass.']]],
    r30: ['Range 30 Minutes', [['Warm-up and practice swings', 'Loosen the shoulders and hips, then make 10 practice swings from 9 to 3 o’clock with a PW.', 'Start with half practice swings and feel the body moving the arms.'], ['PW half swings', 'Hit 15 half swings from 9 to 3 o’clock with a PW. The goal is solid contact every time.', 'Aim at the nearest flag and just make solid contact first.'], ['7 iron full swings', 'Pick a target flag for every ball, hit 20, hold the finish for 3 seconds.', 'Change target every ball instead of hitting the same shot over and over.'], ['Hybrid or 5 wood', 'Hit 10 at 75% effort, teed up slightly.', 'Tee height: half the ball above the clubhead.'], ['Finish with chips', 'Hit 10 bump and runs on the practice green, or 30-yard PW shots from the mat.', 'End with the short game so your touch stays sharp for the shots you hit most.']]],
    p20: ['Putting 20 Minutes', [['Rail putts', 'Lay two clubs parallel on the ground as rails and hit 10 putts from 1 metre without touching them.', 'The rails are just wider than the putter head, so it moves straight back and through.'], ['Gate Drill', 'Push two tees in in front of the ball as a gate and hit 15 putts from 1 metre through it.', 'The tees are just wider than the ball. If the ball hits one, the face wasn’t square.'], ['Coin drill', 'Putt the ball off a coin. After the stroke, see the coin and count to one before looking up. 10 putts from 2 metres.', 'After the ball has gone, your eyes stay on the coin, so your head doesn’t lift early.'], ['Stop it in the circle', 'Mark a circle around the hole with a radius of one putter length. Putt 5 balls each from 8, 12 and 16 steps and stop them inside.', 'Long putts don’t need to drop. Inside a putter length, the next one is easy.']]],
    p30: ['Putting 30 Minutes', [['Gate Drill warm-up', '10 putts from 1 metre to feel a square putter face.', 'The tees are just wider than the ball; roll it through the middle.'], ['Circle Drill', '8 balls 1 metre around the hole; hole them all in a row before moving back to 1.5 metres.', 'With the hole in the middle, push 8 tees in a circle at 1 metre and put a ball by each.'], ['Pace drill', 'Lay a club 40 cm behind the hole. Hit 10 putts from 3 metres that go past the hole but don’t touch the club.', 'A ball that stops between the hole and the club is rolling at the best pace to go in.'], ['Lag Ladder', 'Tees at 10, 15 and 20 steps. Each putt must go further than the last but not past 20 steps.', 'This is about distance. A little off line is fine.'], ['Par 18 putting game', 'Pick 9 holes on the practice green with different lengths and slopes, par 2 each. As a beginner, aim for 22 or less.', 'One ball per hole, read every putt like it counts, then add up your score.']]],
    r60: ['Range 60 Minutes', [['Warm-up and practice swings', 'Stretch, then make 15 half practice swings with a PW.', 'Start with half practice swings and feel the body moving the arms.'], ['Short-iron half swings', 'Hit 10 half swings each with PW and 9 iron, checking your contact.', 'Aim at the nearest flag and just make solid contact first.'], ['7 iron target practice', 'Change target every ball and count how many of 20 finish near the target.', 'Lay a club down to aim every ball, then change target.'], ['Tee shots', 'Hit 10 with the driver or 5 wood at 75%, picturing the edges of a fairway.', 'Tee height: half the ball above the clubhead.'], ['Chipping', 'Practise bump and runs and standard chips on the practice green using the towel landing spot.', 'Lay a towel one step onto the green; land the ball on it first.'], ['Putting', 'One round of the 1-metre Circle Drill, then 5 long putts of 10+ steps.', 'With the hole in the middle, push 8 tees in a circle at 1 metre.']]]
  };


  EN.ruleAreas = { basics: ['Basics', 'What to know before you start.'], tee: ['Teeing Area', 'The first shot on every hole.'], general: ['General Area', 'Fairway, rough and trees.'], bunker: ['Bunker', 'What you can and can’t do in the sand.'], penalty: ['Penalty Area', 'Yellow and red stakes: water and other penalty areas.'], lost: ['Lost & Out of Bounds', 'When you can’t find the ball or hit it past the white stakes.'], green: ['Putting Green', 'Marking, cleaning, repairing and the flagstick.'], relief: ['Free Relief', 'Ground under repair, standing water, cart paths and embedded balls.'] };
  /* Rules in the same order as data.js: [question, answer, rule reference] */
  EN.rules = [
    ['How many clubs can I carry?', 'Fourteen at most. If you find an extra one after starting, it’s a 2-stroke penalty for each hole, up to 4 strokes per round, and you must declare it out of play right away.', '4.1b'],
    ['What does “play the ball as it lies” mean?', 'The most basic principle in golf: play the ball from where it stopped. You can’t improve your lie, stance or swing area, for example by breaking branches, pressing down grass or moving fixed objects. Breaking this costs 2 strokes.', '8.1'],
    ['I accidentally hit the ball twice in one swing. Is that a penalty?', 'No penalty. It counts as one stroke, and you play on from where the ball stopped.', '10.1a'],
    ['What if I play someone else’s ball?', 'In stroke play it’s a 2-stroke penalty and you must go back and play your own ball; the strokes with the wrong ball don’t count. In match play you lose the hole. Marking your ball before the round avoids this.', '6.3c'],
    ['What if I kick my own ball while searching for it?', 'No penalty. Put it back where it was (estimate the spot if you don’t know it).', '7.4'],
    ['What’s the difference between stroke play and match play?', 'Stroke play adds up your strokes over 18 holes and the lowest total wins. Match play is decided hole by hole and the player who wins the most holes wins. For the same breach, match play is usually “loss of hole” rather than 2 strokes.', '3'],
    ['Where can I tee the ball?', 'In the rectangle between the two tee markers and up to two club-lengths behind them. You can stand outside it, but the ball must be inside.', '6.2b'],
    ['What if I tee off from outside the teeing area?', 'In stroke play it’s 2 strokes and you must replay from inside the teeing area (the first stroke doesn’t count). In match play your opponent may make you replay it, with no penalty.', '6.1b'],
    ['The ball fell off the tee before I swung. What now?', 'No penalty. Put it back on the tee and hit again. If you swung and missed, that counts as a stroke.', '6.2b'],
    ['Can I press down the long grass before I hit?', 'No. You can’t improve the conditions affecting your stroke. You can take a normal stance and address the ball, but deliberately pressing grass down or breaking branches is 2 strokes.', '8.1a'],
    ['Can I move leaves and small stones near my ball?', 'Yes. Loose impediments (leaves, twigs, stones) can be removed anywhere, but if your ball moves while you do it, that’s 1 stroke and you put it back (except on the putting green).', '15.1'],
    ['My ball is unplayable (under a tree, in a bush). What can I do?', 'You can declare it unplayable. For 1 stroke, choose one option: ① replay from where you last hit; ② drop any distance back on a line from the hole through the ball; ③ drop within two club-lengths of the ball, no nearer the hole.', '19.2'],
    ['My ball is plugged in its own pitch mark. What now?', 'In the general area you get free relief: drop within one club-length of the spot right behind the ball, no nearer the hole. This doesn’t apply in bunkers.', '16.3'],
    ['Can my club touch the sand when I address the ball in a bunker?', 'No. Touching the sand at address, in a practice swing or on the backswing is 2 strokes. The club only touches the sand during the stroke.', '12.2b'],
    ['Can I move leaves or stones in a bunker?', 'Yes (since 2019). Loose impediments and movable obstructions such as rakes can be removed, as long as the ball doesn’t move.', '12.2a'],
    ['My ball is unplayable in a bunker. What now?', 'For 1 stroke: replay from where you last hit, drop back in the bunker on the line from the hole, or drop within two club-lengths in the bunker. Or for 2 strokes, drop outside the bunker on the line from the hole through the ball.', '19.3'],
    ['What should I do after playing out of a bunker?', 'Rake your footprints and the mark from your shot, and put the rake back. It’s etiquette, not a rule, but it matters a lot.', 'Etiquette'],
    ['What’s the difference between yellow and red stakes?', 'Both mark penalty areas. With yellow, for 1 stroke you can replay from where you last hit, or drop back on the line from the hole through the point where the ball last crossed the edge. Red adds one more option: drop within two club-lengths of that crossing point, no nearer the hole.', '17.1d'],
    ['Can I just play the ball out of a penalty area?', 'Yes, with no penalty. Since 2019 you can ground your club, touch the water and move loose impediments in a penalty area.', '17.1b'],
    ['My ball went toward the water but I didn’t see where. What now?', 'You can only use penalty-area relief if it’s known or virtually certain the ball is in the penalty area. If not, treat it as a lost ball (replay from where you last hit).', '17.1c'],
    ['How long can I search for my ball?', 'Three minutes, starting when you (or your caddie) begin searching. If it isn’t found in 3 minutes, it’s lost.', '18.2a'],
    ['My ball is lost or out of bounds (white stakes). What now?', '“Stroke and distance”: take a 1-stroke penalty and replay from where you last hit. If your tee shot goes out of bounds, your next tee shot is your third stroke.', '18.2b'],
    ['What is a provisional ball?', 'If your ball might be lost or out of bounds (but not in a penalty area), announce “I’m playing a provisional” and hit a second ball. It saves walking back. If you find the original, play it; if not, play the provisional with a 1-stroke penalty.', '18.3'],
    ['My friend says I can drop in the fairway for 2 strokes after going out of bounds?', 'That’s Model Local Rule E-5, and it only applies when the course or competition adopts it: for 2 strokes, drop near where the ball was lost or went out, at the edge of the fairway. It’s meant to speed up casual golf and isn’t used in most official competitions.', 'Local Rule E-5'],
    ['Can I pick up my ball on the green and clean it?', 'Yes. Put a ball marker right behind the ball, lift and clean it, then put it back in the same spot.', '13.1b'],
    ['Can I leave the flagstick in when I putt?', 'Yes (since 2019). If the ball hits the flagstick in the hole there’s no penalty, and if it ends up in the hole it’s holed.', '13.2a'],
    ['My putt hit another player’s ball on the green?', 'In stroke play, when both balls are on the green, hitting another ball is 2 strokes. Their ball goes back to its spot and you play yours from where it stopped. Ask others to mark before you putt.', '11.1a'],
    ['Can I repair pitch marks and spike marks on the green?', 'Yes. Since 2019 you can repair almost any damage on the green (pitch marks, spike marks, animal damage), but not natural imperfections or wear.', '13.1c'],
    ['My ball is hanging on the edge of the hole. Can I wait?', 'Once you reach the hole you can wait 10 more seconds. If it drops within 10 seconds, it’s holed with your last stroke; if it drops later, add 1 stroke.', '13.3a'],
    ['My ball stopped next to a cart path or sprinkler head?', 'Those are immovable obstructions and you get free relief: find the nearest point of complete relief and drop within one club-length, no nearer the hole. You can also choose to play it as it lies.', '16.1'],
    ['What about ground under repair or temporary water?', 'Same as obstructions: free relief, nearest point of complete relief, drop within one club-length. Ground under repair is usually marked with blue stakes or white lines.', '16.1'],
    ['How do I drop the ball correctly?', 'Let it fall straight down from knee height. It must land in and stay in the relief area. If it rolls out, drop again; if it rolls out again, place it where it landed the second time.', '14.3'],
    ['Which club do I use to measure a club-length?', 'The longest club in your bag except the putter (usually the driver). For two club-lengths, measure twice.', 'Definition']
  ];
  EN.penaltyTable = [['Swing and miss', 'Counts as 1 stroke'], ['Hitting the ball twice by accident', 'No penalty'], ['Putt hits the flagstick', 'No penalty'], ['Kicking your ball while searching', 'No penalty'], ['Lost ball / out of bounds', '1 stroke + replay'], ['Yellow / red penalty area', '1 stroke'], ['Unplayable ball', '1 stroke'], ['Club touches sand at address in a bunker', '2 strokes'], ['Playing the wrong ball', '2 strokes'], ['Teeing off outside the teeing area', '2 strokes'], ['Putt hits another ball on the green', '2 strokes'], ['More than 14 clubs', '2 strokes per hole (max 4)']];
