  EN.etiquette = [['Safety first', 'Check nobody is near before you swing. If your ball might hit someone, shout “Fore!”'], ['Keep up the pace', 'Be ready when it’s your turn (ready golf) and try to play each shot within 40 seconds. If the group behind is waiting, let them through.'], ['Look after the course', 'Replace divots or fill them with sand, rake bunkers and repair pitch marks on the green.'], ['Respect the line', 'Don’t step on another player’s line between ball and hole, stay quiet and out of their sight when they play.'], ['Score honestly', 'Golf is self-refereed. Write down your score right after each hole.']];
  /* Glossary in data.js order: [group, English term, short name, definition, auto-link words] */
  EN.glossary = [
    ['Scoring', 'Par', 'Par', 'The number of strokes a hole is expected to take, usually 3, 4 or 5. The 18 holes usually add up to 72.', ['par']],
    ['Scoring', 'Birdie', 'Birdie', 'One stroke under par.', ['birdie']],
    ['Scoring', 'Bogey', 'Bogey', 'One stroke over par. A good first goal for beginners is a bogey on every hole, about 90 for the round.', ['bogey']],
    ['Scoring', 'Double Bogey', 'Double bogey', 'Two strokes over par.', ['double bogey']],
    ['Scoring', 'Handicap', 'Handicap', 'A number showing roughly how many strokes over par you usually shoot, so players of different levels can compete fairly. A 28 handicap is about 100 strokes.', ['handicap']],
    ['Scoring', 'Break 100', 'Breaking 100', 'Shooting 99 or less for 18 holes, the first milestone for many beginners.', ['break 100']],
    ['The Course', 'Tee Box', 'Teeing area', 'Where you play the first shot on each hole, marked by two tee markers.', ['teeing area']],
    ['The Course', 'Fairway', 'Fairway', 'The short grass between the tee and the green. The easiest place to play from.', ['fairway']],
    ['The Course', 'Rough', 'Rough', 'The longer grass beside the fairway. The ball sits down and is harder to hit.', ['rough']],
    ['The Course', 'Green', 'Green', 'Where the hole is. The grass is cut shortest and you only use the putter.', ['putting green']],
    ['The Course', 'Fringe', 'Fringe', 'The ring of slightly longer grass around the green.', ['fringe']],
    ['The Course', 'Bunker', 'Bunker', 'A sand-filled hollow on the course. Your club can’t touch the sand at address.', ['bunker']],
    ['The Course', 'Penalty Area', 'Penalty area', 'An area marked with yellow or red stakes, usually water. You can take relief for 1 stroke.', ['penalty area']],
    ['The Course', 'OB (Out of Bounds)', 'Out of bounds', 'Beyond the white stakes. Out of bounds costs 1 stroke and you replay from where you last hit.', ['out of bounds']],
    ['Clubs', 'Loft', 'Loft', 'How far the clubface tilts back. More loft means a higher, shorter shot. A driver is about 10°, wedges about 50–60°.', ['loft']],
    ['Clubs', 'Bounce', 'Bounce', 'The angle on the sole of a wedge that lets it skid through sand or soft grass instead of digging.', ['bounce']],
    ['Clubs', 'Lie Angle', 'Lie angle', 'The angle between the shaft and the ground. If it doesn’t suit your height, shots tend to go left or right.', ['lie angle']],
    ['Clubs', 'Shaft Flex', 'Shaft flex', 'How stiff the shaft is: L (ladies), A (senior), R (regular), S (stiff). Slower swings suit softer shafts.', ['shaft flex']],
    ['Clubs', 'Hybrid', 'Hybrid', 'A mix of wood and iron. Easier to get airborne than a long iron, great for beginners.', ['hybrid']],
    ['Clubs', 'Wedge', 'Wedge', 'The most lofted irons: PW, GW, SW, LW, used for short shots and bunkers.', ['wedge']],
    ['Shots', 'Fat', 'Fat shot', 'The club hits the ground before the ball and it doesn’t go far.', ['fat']],
    ['Shots', 'Thin / Top', 'Thin / topped shot', 'The club hits the top half of the ball, which flies low or rolls along the ground.', ['thin']],
    ['Shots', 'Slice', 'Slice', '(Right-handed) The ball curves a long way right. The most common beginner ball flight.', ['slice']],
    ['Shots', 'Hook', 'Hook', '(Right-handed) The ball curves a long way left.', ['hook']],
    ['Shots', 'Shank', 'Shank', 'The ball comes off the hosel, where the head meets the shaft, and shoots off to the right.', ['shank']],
    ['Shots', 'Divot', 'Divot', 'The slice of turf taken after an iron shot. On a good iron shot the divot is in front of the ball.', ['divot']],
    ['Shots', 'Sweet Spot', 'Sweet spot', 'The centre of the clubface, where contact is most efficient. It feels soft and goes furthest.', ['sweet spot']],
    ['Stats', 'GIR', 'Green in regulation', 'Reaching the green in par minus 2 strokes, e.g. on a par 4 in 2.', ['GIR']],
    ['Stats', 'Fairway Hit', 'Fairway hit', 'How often your tee shot on par 4s and 5s finishes in the fairway.', []],
    ['Stats', 'Up & Down', 'Up and down', 'Missing the green, then getting down in two: one chip and one putt.', ['up and down']],
    ['Stats', 'Scrambling', 'Scrambling', 'How often you still make par or better after missing the green in regulation.', ['scrambling']],
    ['Stats', 'Sand Save', 'Sand save', 'Getting up and down from a greenside bunker in one putt or fewer.', []],
    ['Stats', '3-Putt', 'Three-putt', 'Taking 3 or more putts on a green. The easiest place for beginners to save strokes.', ['three-putt']],
    ['Rules', 'Penalty Stroke', 'Penalty stroke', 'Strokes added for breaking a rule or taking relief, e.g. 1 for out of bounds or water.', ['penalty stroke']],
    ['Rules', 'Provisional Ball', 'Provisional ball', 'If your ball might be lost or out of bounds, announce it and hit another one to save walking back.', ['provisional']],
    ['Rules', 'Drop', 'Drop', 'When taking relief, let the ball fall from knee height so it stops in the relief area.', ['drop']],
    ['Rules', 'Free Relief', 'Free relief', 'When your ball is on a cart path, ground under repair and similar, you can move it without penalty.', ['free relief']],
    ['Rules', 'Ready Golf', 'Ready golf', 'In casual golf, whoever is ready plays first, not necessarily the player furthest away. It speeds things up.', ['ready golf']],
    ['Rules', 'Max Score', 'Max score per hole', 'In casual golf, beginners can pick up once they reach double par and write that down, so they don’t hold anyone up.', ['double par']]
  ];
